const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function scan(page) {
  await delay(page.ms);
  console.log("scanned " + page.name);
}

async function scanAll(pages, size) {
  for (let i = 0; i < pages.length; i += size) {
    await Promise.all(pages.slice(i, i + size).map((page) => scan(page)));
    console.log("next");
  }
}

scanAll([{ name: "a", ms: 40 }, { name: "b", ms: 10 }, { name: "c", ms: 10 }], 2);
